#include <bits/stdc++.h>using namespace std;#define int long long#define double long double int32_t main() {    ios::sync_with_stdio(false);    cin.tie(0);    cout.tie(0);     int n, m, k;    cin >> n >> m >> k;    vector<int> distance(n + 1, -1);    vector<int> node(n + 1);    vector<vector<int>> graph(n + 1, vector<int>());    for (int i = 1; i <= n; i++) {        cin >> node[i];    }     for (int i = 0; i < m; i++) {        int u, v;        cin >> u >> v;        graph[u].push_back(v);        graph[v].push_back(u);    }     queue<int> q;    int start_node = 1;    distance[start_node] = 0;    q.push(start_node);     while (!q.empty()) {        int current = q.front();        q.pop();        for (auto neighbor : graph[current]) {            if (distance[neighbor] == -1) {                distance[neighbor] = distance[current] + 1;                q.push(neighbor);            }        }    }     vector<int> product(k + 1, 0);    for (int i = 1; i <= n; i++) {        int p_type = node[i];        product[p_type] = max(product[p_type], distance[i]);    }     for (int i = 1; i <= k; i++) {        cout << product[i] << " ";    }}